<?php
require_once __DIR__.'/../includes/auth.php';wajibRole('penghuni');require_once __DIR__.'/../config/database.php';
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$error='';$success='';$q=$pdo->prepare('SELECT id_penghuni,nama FROM penghuni WHERE id_user=:id LIMIT 1');$q->execute(['id'=>$_SESSION['id_user']]);$p=$q->fetch();if(!$p)exit('Data penghuni belum terhubung dengan akun ini.');
if($_SERVER['REQUEST_METHOD']==='POST'){$token=$_POST['csrf_token']??'';$tanggal=trim($_POST['tanggal_keluhan']??'');$isi=trim($_POST['isi_keluhan']??'');$kategori=trim($_POST['kategori_keluhan']??'');if(!hash_equals($_SESSION['csrf_token'],$token))$error='Permintaan tidak valid.';elseif(!$tanggal||!$isi||!in_array($kategori,['fasilitas','kebersihan','keamanan','lainnya'],true))$error='Semua data wajib diisi.';elseif(mb_strlen($isi)<10)$error='Isi keluhan minimal 10 karakter.';else{try{$s=$pdo->prepare("INSERT INTO keluhan (id_penghuni,tanggal_keluhan,isi_keluhan,kategori_keluhan,status_penanganan) VALUES (:id,:tanggal,:isi,:kategori,'menunggu')");$s->execute(['id'=>$p['id_penghuni'],'tanggal'=>$tanggal,'isi'=>$isi,'kategori'=>$kategori]);$success='Keluhan berhasil dikirim dan menunggu penanganan pengelola.';}catch(PDOException $e){$error='Keluhan gagal dikirim. Periksa struktur tabel keluhan.';error_log($e->getMessage());}}}
$q=$pdo->prepare('SELECT * FROM keluhan WHERE id_penghuni=:id ORDER BY tanggal_keluhan DESC,id_keluhan DESC');$q->execute(['id'=>$p['id_penghuni']]);$data=$q->fetchAll();function ePK($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function tPK($v){return $v?date('d M Y',strtotime($v)):'-';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keluhan Saya | KosSpace</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/css/app.css" rel="stylesheet"></head><body><div class="app-shell d-flex"><aside class="sidebar"><a class="brand" href="dashboard.php"><span class="brand-mark"><i class="bi bi-house-heart-fill"></i></span><span>KosSpace</span></a><div class="sidebar-label">Menu penghuni</div><nav class="side-nav"><a href="dashboard.php"><i class="bi bi-grid-1x2-fill"></i>Dashboard</a><a href="pembayaran.php"><i class="bi bi-wallet2"></i>Pembayaran</a><a class="active" href="keluhan.php"><i class="bi bi-chat-square-text"></i>Keluhan</a><a href="ganti_password.php"><i class="bi bi-shield-lock"></i>Pengaturan akun</a></nav><div class="sidebar-footer"><i class="bi bi-shield-check me-1"></i> Portal Penghuni<br>Sampaikan keluhan terkait kos di sini.</div></aside><main class="app-main"><header class="topbar"><div><div class="topbar-kicker">Workspace / Penghuni</div><div class="topbar-title">Layanan keluhan</div></div><div class="user-chip"><div class="avatar"><i class="bi bi-person-fill"></i></div><div class="d-none d-sm-block"><div class="user-name"><?=ePK($_SESSION['nama']??'Penghuni')?></div><div class="user-role">Penghuni kos</div></div><a href="../logout.php" class="btn btn-outline-secondary ms-1"><i class="bi bi-box-arrow-right me-1"></i><span class="d-none d-sm-inline">Keluar</span></a></div></header><section class="page-heading"><div><div class="eyebrow">Layanan penghuni</div><h1>Keluhan Saya</h1><p>Kirim keluhan dan pantau status penanganannya.</p></div></section><?php if($success):?><div class="alert alert-success"><i class="bi bi-check-circle me-2"></i><?=ePK($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><i class="bi bi-exclamation-circle me-2"></i><?=ePK($error)?></div><?php endif;?><div class="row g-3"><div class="col-lg-5"><section class="panel"><h2 class="panel-title">Kirim keluhan</h2><div class="panel-subtitle mb-4">Jelaskan masalah yang kamu alami agar pengelola dapat menanganinya.</div><form method="post"><input type="hidden" name="csrf_token" value="<?=ePK($_SESSION['csrf_token'])?>"><div class="mb-3"><label class="form-label">Tanggal keluhan</label><input type="date" name="tanggal_keluhan" class="form-control" value="<?=ePK($_POST['tanggal_keluhan']??date('Y-m-d'))?>" required></div><div class="mb-3"><label class="form-label">Kategori</label><select name="kategori_keluhan" class="form-select" required><option value="">Pilih kategori</option><?php foreach(['fasilitas','kebersihan','keamanan','lainnya'] as $kat):?><option value="<?=$kat?>" <?=($_POST['kategori_keluhan']??'')===$kat?'selected':''?>><?=ucfirst($kat)?></option><?php endforeach;?></select></div><div class="mb-4"><label class="form-label">Isi keluhan</label><textarea name="isi_keluhan" class="form-control" rows="6" placeholder="Contoh: Lampu kamar mandi tidak menyala..." required><?=ePK($_POST['isi_keluhan']??'')?></textarea></div><button class="btn btn-primary w-100"><i class="bi bi-send me-2"></i>Kirim Keluhan</button></form></section></div><div class="col-lg-7"><section class="panel"><div class="mb-4"><h2 class="panel-title">Riwayat keluhan</h2><div class="panel-subtitle">Pantau perkembangan laporan yang sudah kamu kirim.</div></div><?php if(!$data):?><div class="empty-state"><i class="bi bi-chat-square-text"></i><strong class="d-block text-dark mb-1">Belum ada keluhan</strong><span>Jika ada masalah di kos, kamu bisa melaporkannya melalui formulir.</span></div><?php else:?><div class="d-grid gap-3"><?php foreach($data as $r):?><div class="p-3" style="border:1px solid var(--ks-border);border-radius:13px"><div class="d-flex justify-content-between gap-3"><div><div class="fw-bold"><?=ePK($r['kategori_keluhan'])?></div><div class="text-secondary small mt-1"><?=tPK($r['tanggal_keluhan'])?></div></div><?php if($r['status_penanganan']==='selesai'):?><span class="soft-badge"><i class="bi bi-check-circle"></i>Selesai</span><?php elseif($r['status_penanganan']==='diproses'):?><span class="soft-badge pending"><i class="bi bi-arrow-repeat"></i>Diproses</span><?php else:?><span class="soft-badge neutral"><i class="bi bi-clock"></i>Menunggu</span><?php endif;?></div><div class="mt-3 text-secondary" style="line-height:1.7"><?=nl2br(ePK($r['isi_keluhan']))?></div></div><?php endforeach;?></div><?php endif;?></section></div></div><footer class="app-footer">&copy; <?=date('Y')?> KosSpace · Sistem Informasi Pengelolaan Kos Mahasiswa</footer></main></div></body></html>